-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.admin_announcements(max_rows integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(public.announcement_json(x) order by x.created_at desc, x.id desc), '[]'::jsonb)
    from (
      select a.* from public.announcements a
       order by a.created_at desc, a.id desc
       limit least(greatest(coalesce(max_rows, 100), 1), 200)
    ) x;
$function$;

grant execute on function public.admin_announcements(max_rows integer) to service_role;
